// Resolves the request window and builds everything the HTTP nodes need.
//
// Why this runs in a Code node rather than in the HTTP node expressions:
// n8n denies $env access inside HTTP node expression previews, so the store
// URL and credentials are read here and passed downstream as plain fields.
//
// Windows are computed in the business timezone, then converted to UTC. The
// WooCommerce REST API treats `after` and `before` as strictly exclusive, so
// the lower bound is shifted back one second to keep midnight orders in.

const PERIODS = ['today', 'yesterday', 'last_7_days', 'last_30_days', 'custom'];
const MAX_WINDOW_DAYS = 92;
const ALL_STATUSES = 'pending,processing,on-hold,completed,cancelled,refunded,failed';

const input = $input.first().json;

const storeUrl = ($env.WOO_STORE_URL || '').replace(/\/+$/, '');
const timezone = $env.BUSINESS_TIMEZONE || 'UTC';
const consumerKey = $env.WOO_CONSUMER_KEY || '';
const consumerSecret = $env.WOO_CONSUMER_SECRET || '';

function invalid(code, message) {
  return [{ json: { valid: false, status: 'invalid_input', error: { code, message } } }];
}

if (!storeUrl || !consumerKey || !consumerSecret) {
  return [{
    json: {
      valid: false,
      status: 'upstream_error',
      error: { code: 'missing_config', message: 'WooCommerce environment variables are not set' },
    },
  }];
}

const period = String(input.period ?? 'today').trim();
if (!PERIODS.includes(period)) {
  return invalid('bad_period', `period must be one of ${PERIODS.join(', ')}, got '${period}'`);
}

// Luxon is available in the n8n runtime and handles DST correctly.
const today = DateTime.now().setZone(timezone).startOf('day');

let first;
let last;
let label;

if (period === 'today') {
  first = today;
  last = today;
  label = 'Today';
} else if (period === 'yesterday') {
  first = today.minus({ days: 1 });
  last = first;
  label = 'Yesterday';
} else if (period === 'last_7_days') {
  first = today.minus({ days: 6 });
  last = today;
  label = 'Last 7 days';
} else if (period === 'last_30_days') {
  first = today.minus({ days: 29 });
  last = today;
  label = 'Last 30 days';
} else {
  const rawFrom = String(input.date_from ?? '').trim();
  const rawTo = String(input.date_to ?? '').trim();
  if (!rawFrom || !rawTo) {
    return invalid('missing_dates', 'period=custom requires both date_from and date_to');
  }
  const pattern = /^\d{4}-\d{2}-\d{2}$/;
  for (const [value, field] of [[rawFrom, 'date_from'], [rawTo, 'date_to']]) {
    if (!pattern.test(value)) {
      return invalid('bad_date', `${field} must be YYYY-MM-DD, got '${value}'`);
    }
  }
  first = DateTime.fromISO(rawFrom, { zone: timezone }).startOf('day');
  last = DateTime.fromISO(rawTo, { zone: timezone }).startOf('day');
  // fromISO accepts the shape but still rejects impossible dates like 2026-08-32.
  if (!first.isValid) {
    return invalid('bad_date', `date_from must be YYYY-MM-DD, got '${rawFrom}'`);
  }
  if (!last.isValid) {
    return invalid('bad_date', `date_to must be YYYY-MM-DD, got '${rawTo}'`);
  }
  if (last < first) {
    return invalid('inverted_range', 'date_to must not precede date_from');
  }
  const span = last.diff(first, 'days').days + 1;
  if (span > MAX_WINDOW_DAYS) {
    return invalid('window_too_large', `window spans ${span} days, maximum is ${MAX_WINDOW_DAYS}`);
  }
  label = `${rawFrom} to ${rawTo}`;
}

const spanDays = last.diff(first, 'days').days + 1;

// Exclusive bounds: shift `after` back one second so midnight orders survive.
function bounds(windowFirst, windowLast) {
  const start = windowFirst.startOf('day');
  const end = windowLast.startOf('day').plus({ days: 1 });
  return {
    after: start.minus({ seconds: 1 }).toUTC().toFormat("yyyy-MM-dd'T'HH:mm:ss"),
    before: end.toUTC().toFormat("yyyy-MM-dd'T'HH:mm:ss"),
    utc_from: start.toUTC().toFormat("yyyy-MM-dd'T'HH:mm:ss"),
    utc_to: end.toUTC().toFormat("yyyy-MM-dd'T'HH:mm:ss"),
  };
}

const current = bounds(first, last);
const prevLast = first.minus({ days: 1 });
const prevFirst = prevLast.minus({ days: spanDays - 1 });
const previous = bounds(prevFirst, prevLast);

return [{
  json: {
    valid: true,
    compare: input.compare !== false,
    ordersUrl: `${storeUrl}/wp-json/wc/v3/orders`,
    statuses: ALL_STATUSES,
    // Built here, not in the HTTP node: Buffer is available in Code nodes but
    // not in HTTP node expressions, where it silently yields a broken header.
    // The raw key and secret deliberately do not leave this node.
    authHeader: 'Basic ' + Buffer.from(`${consumerKey}:${consumerSecret}`).toString('base64'),
    period: {
      name: period,
      label,
      date_from: first.toFormat('yyyy-MM-dd'),
      date_to: last.toFormat('yyyy-MM-dd'),
      timezone,
      utc_from: current.utc_from,
      utc_to: current.utc_to,
    },
    current,
    previous: {
      date_from: prevFirst.toFormat('yyyy-MM-dd'),
      date_to: prevLast.toFormat('yyyy-MM-dd'),
      ...previous,
    },
  },
}];

// Reduces two order windows into the tool contract.
//
// Mirrors scripts/orders_summary.py so the two can be compared to the cent.
// Any divergence between them is a bug in one of the two, never a rounding
// difference: both round to two decimals at the same points.

const REVENUE_STATUSES = ['pending', 'processing', 'on-hold', 'completed'];

const config = $('prepare-request').first().json;
// Always Output Data is enabled on both HTTP nodes so that an empty window
// does not halt the workflow before the contract is built. The cost is a
// single placeholder item with no order fields, filtered out here.
function orders(nodeName) {
  return $(nodeName)
    .all()
    .map((item) => item.json)
    .filter((order) => order && order.id !== undefined);
}

const currentOrders = orders('fetch-current');
const previousOrders = orders('fetch-previous');

function money(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function compute(orders) {
  const byStatus = {};
  let gross = 0;
  let refunds = 0;
  let revenueOrders = 0;
  let currency = '';

  for (const order of orders) {
    const status = String(order.status);
    const total = parseFloat(order.total) || 0;
    currency = currency || String(order.currency || '');

    if (!byStatus[status]) {
      byStatus[status] = { count: 0, total: 0 };
    }
    byStatus[status].count += 1;
    byStatus[status].total += total;

    // Refunds are only subtracted for orders that contributed to gross.
    // Orders with status=refunded are already excluded from revenue, so
    // subtracting their refunds too would deduct the same money twice.
    if (REVENUE_STATUSES.includes(status)) {
      gross += total;
      revenueOrders += 1;
      for (const refund of order.refunds || []) {
        refunds += Math.abs(parseFloat(refund.total) || 0);
      }
    }
  }

  for (const bucket of Object.values(byStatus)) {
    bucket.total = money(bucket.total);
  }

  const sorted = {};
  for (const key of Object.keys(byStatus).sort()) {
    sorted[key] = byStatus[key];
  }

  return {
    orders_count: orders.length,
    revenue_orders_count: revenueOrders,
    revenue_gross: money(gross),
    refunds_total: money(refunds),
    revenue_net: money(gross - refunds),
    aov: revenueOrders ? money(gross / revenueOrders) : null,
    currency: currency || null,
    by_status: sorted,
  };
}

function delta(current, previous) {
  if (current === null || previous === null) {
    return { absolute: null, percent: null };
  }
  const diff = money(current - previous);
  if (previous === 0) {
    return { absolute: diff, percent: null };
  }
  return { absolute: diff, percent: Math.round((diff / previous) * 1000) / 10 };
}

const metrics = compute(currentOrders);

let comparison = null;
if (config.compare) {
  const previousMetrics = compute(previousOrders);
  comparison = {
    date_from: config.previous.date_from,
    date_to: config.previous.date_to,
    metrics: previousMetrics,
    deltas: {
      orders_count: delta(metrics.orders_count, previousMetrics.orders_count),
      revenue_gross: delta(metrics.revenue_gross, previousMetrics.revenue_gross),
      revenue_net: delta(metrics.revenue_net, previousMetrics.revenue_net),
      aov: delta(metrics.aov, previousMetrics.aov),
    },
  };
}

return [{
  json: {
    status: currentOrders.length ? 'ok' : 'no_data',
    period: config.period,
    metrics,
    comparison,
    notes: [
      'Refunds are attributed to the parent order date, not the refund date.',
      'Revenue excludes cancelled, failed and refunded orders.',
    ],
    error: null,
  },
}];

// Normalises a rejected request into the same contract shape as a success.
//
// The agent should never have to branch on response shape: same keys every
// time, with `status` and `error` carrying the difference. prepare-request
// has already classified the failure, so this node only reformats it.

const input = $input.first().json;

return [{
  json: {
    status: input.status || 'invalid_input',
    period: null,
    metrics: null,
    comparison: null,
    notes: [],
    error: input.error || {
      code: 'unknown',
      message: 'Request rejected without a reason code',
    },
  },
}];
